# magicadd.py: adds the Magic Add game (Play Zone), its home-page tile and tests.
import base64, hashlib, os, sys
FULL = {'app/src/playzone/MagicAdd.tsx': ('', None), 'app/src/screens/CategoryScreen.tsx': ('', '5576b2c9b9097d3e8d1e0cb1d889d59d'), 'app/e2e/flows.spec.ts': ('', '170166fdff8e874f3af9d469e4311a35'), 'app/e2e/screens/screens.spec.ts': ('', '7ffddbc2da3b306184e921c5900db87e')}
EDITS = {'app/src/playzone/common.tsx': [("| 'trace' | 'dots';", "| 'trace' | 'dots' | 'add';")], 'app/src/screens/PlayZoneScreen.tsx': [("import DotToDot from '../playzone/DotToDot';\n", "import DotToDot from '../playzone/DotToDot';\nimport MagicAdd, { defaultAddLevel } from '../playzone/MagicAdd';\n"), ("  { key: 'dots', emoji: '🖍️', name: 'Connect the Dots', blurb: 'Join 1, 2, 3… and a picture appears', background: '#E3F1FB', border: '#5B9BD0', ink: '#286A98', unlockAfter: 0, isNew: true },\n", "  { key: 'dots', emoji: '🖍️', name: 'Connect the Dots', blurb: 'Join 1, 2, 3… and a picture appears', background: '#E3F1FB', border: '#5B9BD0', ink: '#286A98', unlockAfter: 0, isNew: true },\n  { key: 'add', emoji: '🪄', name: 'Magic Add', blurb: 'Tap numbers that make the magic number', background: '#F3EEFF', border: '#9B7EDE', ink: '#4E3590', unlockAfter: 0, isNew: true },\n"), ("  if (game === 'dots') return defaultDotLevel(age);\n", "  if (game === 'dots') return defaultDotLevel(age);\n  if (game === 'add') return defaultAddLevel(age);\n"), ("        {playing === 'dots' ? <DotToDot {...props} wall={progress?.pictures} onPicture={onPicture} /> : null}\n", "        {playing === 'dots' ? <DotToDot {...props} wall={progress?.pictures} onPicture={onPicture} /> : null}\n        {playing === 'add' ? <MagicAdd {...props} /> : null}\n")], 'app/src/screens/WelcomeScreen.tsx': [("  { key: 'dots', icon: '🖍️', name: 'Connect the Dots', background: '#E3F1FB', border: '#5B9BD0' },\n", "  { key: 'dots', icon: '🖍️', name: 'Connect the Dots', background: '#E3F1FB', border: '#5B9BD0' },\n  { key: 'add', icon: '🪄', name: 'Magic Add', background: '#F3EEFF', border: '#9B7EDE' },\n"), ("line: 'Snake, bubbles, mazes, tracing and dots', icons: ['🐍', '🫧', '🖍️', '✏️'],", "line: 'Snake, bubbles, mazes, dots and magic adding', icons: ['🐍', '🫧', '🪄', '🖍️'],"), ("ribbon: '🆕 CONNECT THE DOTS'", "ribbon: '🆕 MAGIC ADD'")]}
# Check everything first, then write.
for p, (b, orig) in FULL.items():
    if orig is None:
        if os.path.exists(p): sys.exit(p + ' already exists; not applying')
    elif hashlib.md5(open(p, 'rb').read()).hexdigest() != orig:
        sys.exit(p + ' changed since staging; not applying')
texts = {}
for p, pairs in EDITS.items():
    s = open(p, encoding='utf-8').read()
    for old, new in pairs:
        if s.count(old) != 1: sys.exit(f'{p}: anchor found {s.count(old)} times; not applying: {old[:60]!r}')
        s = s.replace(old, new)
    texts[p] = s
for p, (b, _) in FULL.items():
    open(p, 'wb').write(base64.b64decode(b)); print('wrote', p)
for p, s in texts.items():
    open(p, 'w', encoding='utf-8').write(s); print('edited', p)
